"""Generate editor hook examples from the documented, executable source files."""
import argparse
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
EXAMPLES = ROOT / "examples" / "hooks"


def render():
    entries = json.loads((EXAMPLES / "manifest.json").read_text())
    for entry in entries:
        entry["source"] = (EXAMPLES / entry["file"]).read_text()

    return (
        "// Generated by tools/generate-hook-examples.py; do not edit.\n"
        "window.spiderHookExamples = " + json.dumps(entries, indent=2) + ";\n"
    )


if __name__ == "__main__":
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--check", action="store_true")
    args = parser.parse_args()
    target = ROOT / "frontend" / "hook-examples.js"
    content = render()

    if args.check:
        if not target.exists() or target.read_text() != content:
            raise SystemExit("Hook examples are stale; run tools/generate-hook-examples.py")
    else:
        target.write_text(content)
